'use strict';

const uploadService = require('../services/upload.service');

/**
 * POST /api/v1/uploads/presign
 * Generate Cloudinary presigned upload credentials.
 * Client uses these to upload directly to Cloudinary.
 *
 * Security:
 *   - userId extracted from JWT (not from body)
 *   - objectKey generated by backend
 *   - Signature expires in 15 minutes
 */
const presign = async (req, res, next) => {
  try {
    const { purpose, fileName, contentType, fileSizeBytes } = req.body;
    const userId = req.user.userId;

    const result = uploadService.generatePresignedUpload({
      purpose,
      fileName,
      contentType,
      fileSizeBytes: parseInt(fileSizeBytes) || 0,
      userId,
    });

    res.json({ success: true, data: result });
  } catch (err) { next(err); }
};

module.exports = { presign };
